pragma solidity ^0.8.20;

import {ERC20Pausable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

// --- Uniswap v4 Interfaces ---
// These are necessary for the hook contract to compile and interact with Uniswap v4.

/// @dev The key for a pool, defined by the currencies, fee, tick spacing, and hooks.
struct PoolKey {
    address currency0;
    address currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

interface IPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    /// @notice Emitted when a pool is initialized
    event PoolInitialized(
        bytes32 indexed poolId,
        address indexed currency0,
        address indexed currency1,
        uint24 fee,
        int24 tickSpacing
    );

    /// @notice Swaps tokens through a pool
    /// @param key The key of the pool to swap in
    /// @param params The parameters for the swap
    /// @param hookData The data to be passed to the hooks
    /// @return delta The amount of tokens returned to the user
    function swap(PoolKey calldata key, SwapParams calldata params, bytes calldata hookData) external returns (int256 delta);
}

interface IUniswapV4Hooks {
    function getHookCalls() external pure returns (uint16);
    function beforeInitialize(address, address, uint24, int24) external returns (bytes4);
    function afterInitialize(address, address, uint24, int24, int24) external returns (bytes4);
    function beforeModifyPosition(address, int24, int24, int256) external returns (bytes4);
    function afterModifyPosition(address, int24, int24, int256, bytes calldata) external returns (bytes4);
    function beforeSwap(address, IPoolManager.SwapParams calldata) external returns (bytes4);
    function afterSwap(address sender, IPoolManager.SwapParams calldata params, bytes calldata data) external returns (bytes4);
    function beforeDonate(address, uint256, uint256) external returns (bytes4);
    function afterDonate(address, uint256, uint256, bytes calldata) external returns (bytes4);
}

// --- Application-specific Interface ---

interface IINRT {
    function requestWithdrawalFromHook(bytes32 requestId, address user, uint256 amount, string calldata upiId) external;
}


/**
 * @title Indian Rupee Token (INRT)
 * @author Expert Solidity Engineer
 * @notice An ERC20 token backed 1:1 by Indian Rupee bank deposits.
 * @dev This contract manages the minting, burning, and withdrawal process for INRT.
 * It is pausable and owned by a single operator account. Minting is tied to unique
 * bank transaction IDs to prevent double-counting deposits. It interacts with a
 * designated Uniswap v4 hook contract to facilitate crypto-to-UPI withdrawals.
 */
contract INRT is ERC20Pausable, Ownable {
    /// @notice The number of decimals for the token, set to 6 for stablecoin convention.
    uint8 private constant _decimals = 6;

    /// @notice The address of the authorized Uniswap v4 hook contract.
    address public authorizedHook;

    /// @notice Tracks bank transaction IDs that have been used for minting to prevent reuse.
    mapping(string => bool) public processedBankTxIds;

    /// @notice The total amount of INR held in bank reserves, in whole rupees.
    uint256 public totalBankReserves;

    /// @notice Represents a user's request to withdraw INRT for INR.
    struct Withdrawal {
        address user;
        uint256 amount; // Amount in token's smallest unit (e.g., 1 INRT = 1e6)
        string upiId;
        uint256 timestamp;
        bool processed;
    }

    /// @notice Stores all withdrawal requests, keyed by a unique request ID.
    mapping(bytes32 => Withdrawal) public withdrawals;

    // --- Events ---

    /// @notice Emitted when new tokens are minted against a bank deposit.
    event TokensMinted(address indexed to, uint256 amount, string bankTxId);
    /// @notice Emitted when the contract owner processes a withdrawal, burning tokens.
    event WithdrawalProcessed(bytes32 indexed requestId);
    /// @notice Emitted when a hook contract is authorized.
    event HookAuthorized(address indexed hook);
    /// @notice Emitted when a hook contract's authorization is revoked.
    event HookRevoked(address indexed hook);
    /// @notice Emitted when a withdrawal is formally logged by the system.
    event WithdrawalRequested(bytes32 indexed requestId, address indexed user, uint256 amount, string upiId);

    // --- Errors ---

    error AlreadyProcessed();
    error NotAuthorized();
    error InvalidAmount();
    error WithdrawalNotFound();
    error ZeroAddress();

    /// @notice Initializes the ERC20 token with a name and symbol.
    constructor() ERC20("Indian Rupee Token", "INRT") Ownable() {}

    /// @dev Overrides the ERC20 decimals function.
    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }

    // --- Owner-only Administrative Functions ---

    /**
     * @notice Mints new tokens and increases bank reserve total.
     * @dev Can only be called by the owner. Each mint must correspond to a unique bankTxId.
     * @param to The address to receive the minted tokens.
     * @param amount The amount of whole INR deposited (e.g., 100 for 100 INR).
     * @param bankTxId A unique string identifier for the bank deposit transaction.
     */
    function mint(address to, uint256 amount, string calldata bankTxId) external onlyOwner {
        if (processedBankTxIds[bankTxId]) revert AlreadyProcessed();
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();

        processedBankTxIds[bankTxId] = true;
        totalBankReserves += amount;
        uint256 mintAmount = amount * (10 ** _decimals);
        _mint(to, mintAmount);

        emit TokensMinted(to, mintAmount, bankTxId);
    }

    /**
     * @notice Burns a user's tokens and marks a withdrawal request as processed.
     * @dev This is the final step in the withdrawal process, executed by the owner
     * after the off-chain UPI payment has been successfully made.
     * @param requestId The unique ID of the withdrawal request to process.
     */
    function burnAndMarkProcessed(bytes32 requestId) external onlyOwner {
        Withdrawal storage withdrawal = withdrawals[requestId];
        if (withdrawal.user == address(0)) revert WithdrawalNotFound();
        if (withdrawal.processed) revert AlreadyProcessed();

        withdrawal.processed = true;
        _burn(withdrawal.user, withdrawal.amount);

        emit WithdrawalProcessed(requestId);
    }

    /**
     * @notice Authorizes a contract (the Uniswap v4 hook) to request withdrawals.
     * @param hookAddress The address of the hook contract.
     */
    function authorizeHook(address hookAddress) external onlyOwner {
        if (hookAddress == address(0)) revert ZeroAddress();
        authorizedHook = hookAddress;
        emit HookAuthorized(hookAddress);
    }

    /**
     * @notice Revokes authorization for the current hook contract.
     */
    function revokeHook() external onlyOwner {
        emit HookRevoked(authorizedHook);
        authorizedHook = address(0);
    }

    /**
     * @notice Pauses all token transfers.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpauses all token transfers.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // --- Hook-only Function ---

    /**
     * @notice Called by the authorized hook to log a new withdrawal request.
     * @dev This function creates the official record of the withdrawal intent.
     * @param requestId A unique ID for the request.
     * @param user The user who is withdrawing.
     * @param amount The amount of tokens to be withdrawn (in smallest unit).
     * @param upiId The user's UPI ID for the off-chain payment.
     */
    function requestWithdrawalFromHook(bytes32 requestId, address user, uint256 amount, string calldata upiId) external {
        if (msg.sender != authorizedHook) revert NotAuthorized();
        if (withdrawals[requestId].user != address(0)) revert AlreadyProcessed();

        withdrawals[requestId] = Withdrawal({
            user: user,
            amount: amount,
            upiId: upiId,
            timestamp: block.timestamp,
            processed: false
        });

        emit WithdrawalRequested(requestId, user, amount, upiId);
    }

    // --- View Functions ---

    /**
     * @notice Retrieves the details of a specific withdrawal request.
     * @param requestId The ID of the withdrawal to query.
     * @return The Withdrawal struct containing request details.
     */
    function getWithdrawalDetails(bytes32 requestId) external view returns (Withdrawal memory) {
        return withdrawals[requestId];
    }

    /**
     * @notice Calculates the backing ratio of the token.
     * @dev The ratio is total bank reserves divided by total token supply.
     * A value of 1e18 represents a 1.0 ratio.
     * @return The backing ratio, scaled by 1e18. Returns 0 if no tokens are in circulation.
     */
    function getBackingRatio() external view returns (uint256) {
        uint256 ts = totalSupply();
        if (ts == 0) {
            return 0;
        }
        // totalBankReserves is in whole units, totalSupply is in smallest units.
        // Scale reserves to smallest units before calculating the ratio.
        uint256 reservesInSmallestUnit = totalBankReserves * (10 ** _decimals);
        return (reservesInSmallestUnit * 1e18) / ts;
    }

    // --- Internal Hooks ---

    /**
     * @dev Overrides `_mint` to ensure bank reserves are only updated through the public `mint` function.
     * This override is for consistency; the main logic is in the public `mint`.
     */
    function _mint(address to, uint256 amount) internal override {
        super._mint(to, amount);
    }

    /**
     * @dev Overrides `_burn` to decrease the recorded bank reserves whenever tokens are burned.
     * This covers both direct burns (`burn`, `burnFrom`) and withdrawal-related burns.
     */
    function _burn(address from, uint256 amount) internal override {
        super._burn(from, amount);
        uint256 reserveDecrease = amount / (10 ** _decimals);
        // This could have rounding issues if amount is not a multiple of 10**decimals.
        // The assumption is that withdrawals and burns happen in whole token amounts.
        if (totalBankReserves >= reserveDecrease) {
            totalBankReserves -= reserveDecrease;
        } else {
            totalBankReserves = 0; // Should not happen in a 1:1 backed system
        }
    }
}

/**
 * @title CryptoUPIHook
 * @author Expert Solidity Engineer
 * @notice A Uniswap v4 Hook to facilitate USDT -> INRT swaps that trigger UPI withdrawals.
 * @dev This hook listens to `afterSwap` on a specific USDT/INRT pool. When a user
 * swaps USDT for INRT and provides hook data (requestId, upiId), this contract
*  notifies the INRT contract to log a withdrawal request.
 */
contract CryptoUPIHook is IUniswapV4Hooks, Ownable {
    // --- State Variables ---

    IPoolManager public poolManager;
    IINRT public i_inrt;
    address public usdtToken;
    bytes32 public poolId;

    mapping(bytes32 => bool) public processedRequestIds;
    mapping(address => uint256) private _preSwapBalances;

    // --- Constants ---

    /// @dev Hook flags to register for beforeSwap and afterSwap callbacks.
    uint16 internal constant HOOK_FLAGS = 0x0001 | 0x0002; // beforeSwap | afterSwap

    // --- Events ---

    /// @notice Emitted by the hook when it detects a valid withdrawal swap.
    /// @dev This event is intended for a backend service to listen to and initiate the off-chain UPI transfer.
    event WithdrawalRequested(bytes32 indexed requestId, address indexed user, uint256 amount, string upiId);

    // --- Errors ---

    error InvalidHookData();
    error NotPoolManager();
    error AlreadyProcessed();
    error WrongSwap();
    error ZeroAddress();
    error AlreadyInitialized();

    /// @notice Constructor is empty to meet deployment constraints. Use `initialize`.
    constructor() Ownable() {}

    /// @notice One-time initialization of the hook.
    /// @param _poolManager The address of the Uniswap v4 PoolManager.
    /// @param _inrtToken The address of the INRT token contract.
    function initialize(address _poolManager, address _inrtToken) external onlyOwner {
        if (address(poolManager) != address(0)) revert AlreadyInitialized();
        if (_poolManager == address(0) || _inrtToken == address(0)) revert ZeroAddress();

        poolManager = IPoolManager(_poolManager);
        i_inrt = IINRT(_inrtToken);
    }

    /// @notice Sets the specific pool details this hook will service.
    /// @param _poolId The ID of the USDT/INRT pool.
    /// @param _usdtToken The address of the USDT token.
    function setPoolDetails(bytes32 _poolId, address _usdtToken) external onlyOwner {
        if (_usdtToken == address(0)) revert ZeroAddress();
        poolId = _poolId;
        usdtToken = _usdtToken;
    }

    // --- Hook Logic ---

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    /// @inheritdoc IUniswapV4Hooks
    function getHookCalls() external pure override returns (uint16) {
        return HOOK_FLAGS;
    }

    /// @inheritdoc IUniswapV4Hooks
    /// @dev Records the user's INRT balance before a swap occurs.
    function beforeSwap(address sender, IPoolManager.SwapParams calldata params)
        external
        override
        onlyPoolManager
        returns (bytes4)
    {
        // We only care about swaps where INRT is the output token (zeroForOne = false if INRT is token1).
        // This simple implementation records balance for any swap in the pool and filters in afterSwap.
        _preSwapBalances[sender] = IERC20(address(i_inrt)).balanceOf(sender);
        return IUniswapV4Hooks.beforeSwap.selector;
    }

    /// @inheritdoc IUniswapV4Hooks
    /// @dev After a swap, calculates INRT received and triggers the withdrawal request process.
    function afterSwap(address sender, IPoolManager.SwapParams calldata params, bytes calldata data)
        external
        override
        onlyPoolManager
        returns (bytes4)
    {
        // We only act if this is a USDT -> INRT swap, and if there is hook data.
        // This requires knowing which token is token0/token1 to correctly check params.zeroForOne.
        // A simpler check is to see if the INRT balance increased.
        uint256 preSwapBalance = _preSwapBalances[sender];
        delete _preSwapBalances[sender]; // Clean up state

        uint256 postSwapBalance = IERC20(address(i_inrt)).balanceOf(sender);

        if (postSwapBalance > preSwapBalance && data.length > 0) {
            uint256 inrtReceived = postSwapBalance - preSwapBalance;

            (bytes32 requestId, string memory upiId) = abi.decode(data, (bytes32, string));

            if (requestId == bytes32(0)) revert InvalidHookData();
            if (processedRequestIds[requestId]) revert AlreadyProcessed();

            processedRequestIds[requestId] = true;

            emit WithdrawalRequested(requestId, sender, inrtReceived, upiId);

            // Notify the INRT contract to create the formal withdrawal record
            i_inrt.requestWithdrawalFromHook(requestId, sender, inrtReceived, upiId);
        }

        return IUniswapV4Hooks.afterSwap.selector;
    }

    // --- View and Helper Functions ---

    /**
     * @notice Returns key information about the pool this hook is configured for.
     * @return isInitialized True if the pool manager has been set.
     * @return poolUsdtToken The address of the USDT token in the pool.
     * @return poolId_ The ID of the pool.
     */
    function getPoolInfo() external view returns (bool isInitialized, address poolUsdtToken, bytes32 poolId_) {
        return (address(poolManager) != address(0), usdtToken, poolId);
    }

    /**
     * @notice ABI-encodes the data required for a withdrawal swap.
     * @param requestId A unique ID for the request (e.g., generated client-side).
     * @param upiId The user's UPI ID string.
     * @return The encoded bytes data to be passed to the `swap` function's `hookData` parameter.
     */
    function encodeHookData(bytes32 requestId, string calldata upiId) external pure returns (bytes memory) {
        return abi.encode(requestId, upiId);
    }

    // --- Unused Hook Callbacks ---
    // These must be implemented to satisfy the interface but are not used.

    function beforeInitialize(address, address, uint24, int24) external pure override returns (bytes4) {
        return IUniswapV4Hooks.beforeInitialize.selector;
    }

    function afterInitialize(address, address, uint24, int24, int24) external pure override returns (bytes4) {
        return IUniswapV4Hooks.afterInitialize.selector;
    }

    function beforeModifyPosition(address, int24, int24, int256) external pure override returns (bytes4) {
        return IUniswapV4Hooks.beforeModifyPosition.selector;
    }

    function afterModifyPosition(address, int24, int24, int256, bytes calldata) external pure override returns (bytes4) {
        return IUniswapV4Hooks.afterModifyPosition.selector;
    }

    function beforeDonate(address, uint256, uint256) external pure override returns (bytes4) {
        return IUniswapV4Hooks.beforeDonate.selector;
    }

    function afterDonate(address, uint256, uint256, bytes calldata) external pure override returns (bytes4) {
        return IUniswapV4Hooks.afterDonate.selector;
    }
}

